const PRIVATE_KEY = 'YOUR_PRIVATE_KEY_HERE'; // Securely manage this in production (e.g., via environment variables)
const CONTRACT_ADDRESS = '0xYourZKContractAddress'; // Address of a ZK-related contract on Sophon
