            <li key={donation.id}>
              <strong>Amount:</strong> ${donation.amount} <br />
              <strong>Date:</strong> {new Date(donation.date).toLocaleDateString()} <br />
              <strong>Project:</strong> {donation.projectName}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

